import org.apache.commons.lang3.StringUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.tuweni.bytes.Bytes;
import tech.pegasys.teku.ethereum.pow.api.DepositTreeSnapshot;
import tech.pegasys.teku.ethereum.pow.api.schema.LoadDepositSnapshotResult;
import tech.pegasys.teku.infrastructure.exceptions.InvalidConfigurationException;
import tech.pegasys.teku.infrastructure.http.UrlSanitizer;
import tech.pegasys.teku.infrastructure.io.resource.ResourceLoader;
import tech.pegasys.teku.infrastructure.json.JsonUtil;
import tech.pegasys.teku.infrastructure.ssz.sos.SszDeserializeException;
import tech.pegasys.teku.spec.networks.Eth2Network;

public class DepositSnapshotFileLoader {

  public static final Map<Eth2Network, String> DEFAULT_SNAPSHOT_RESOURCE_PATHS =
      Map.of(
          Eth2Network.GNOSIS, "gnosis.ssz",
          Eth2Network.PRATER, "goerli.ssz",
          Eth2Network.MAINNET, "mainnet.ssz",
          Eth2Network.SEPOLIA, "sepolia.ssz",
          Eth2Network.LUKSO, "lukso.ssz",
          Eth2Network.HOLESKY, "holesky.ssz");

  private static final Logger LOG = LogManager.getLogger();

  private final List<DepositSnapshotResource> depositSnapshotResources;

  private DepositSnapshotFileLoader(final List<DepositSnapshotResource> depositSnapshotResources) {
    this.depositSnapshotResources = depositSnapshotResources;
  }

  public List<DepositSnapshotResource> getDepositSnapshotResources() {
    return depositSnapshotResources;
  }

  public LoadDepositSnapshotResult loadDepositSnapshot() {
    for (final DepositSnapshotResource depositSnapshotResource : depositSnapshotResources) {
      final Optional<DepositTreeSnapshot> depositTreeSnapshot =
          loadDepositSnapshotResource(depositSnapshotResource);
      if (depositTreeSnapshot.isPresent()) {
        final DepositTreeSnapshot snapshot = depositTreeSnapshot.get();
        STATUS_LOG.onDepositSnapshot(
            snapshot.getDepositCount(), snapshot.getExecutionBlockHash());
        return LoadDepositSnapshotResult.create(depositTreeSnapshot);
      }
    }
    return LoadDepositSnapshotResult.create(Optional.empty());
  }

  private Optional<DepositTreeSnapshot> loadDepositSnapshotResource(
      final DepositSnapshotResource depositSnapshotResource) {
    final String path = depositSnapshotResource.getPath();
    final String sanitizedResource = UrlSanitizer.sanitizePotentialUrl(path);
    try {
      STATUS_LOG.loadingDepositSnapshotResource(sanitizedResource);
      return Optional.of(loadFromUrl(path));
    } catch (final FileNotFoundException e) {
      if (depositSnapshotResource.isRequired()) {
        LOG.error("Failed to load deposit tree snapshot from {}", sanitizedResource, e);
        throw new InvalidConfigurationException(e.getMessage());
      }
      // Optional resource, skip it and try the next one
      LOG.debug("Optional deposit tree snapshot resource {} not found, skipping", sanitizedResource);
      return Optional.empty();
    } catch (final IOException e) {
      LOG.error("Failed to load deposit tree snapshot from {}", sanitizedResource, e);
      throw new InvalidConfigurationException(
          "Failed to load deposit tree snapshot from "
              + sanitizedResource
              + ": "
              + e.getMessage());
    }
  }

  private DepositTreeSnapshot loadFromUrl(final String path) throws IOException {
    final Bytes snapshotData =
        ResourceLoader.urlOrFile("application/octet-stream, application/json")
            .loadBytes(path)
            .orElseThrow(
                () -> new FileNotFoundException(String.format("File '%s' not found", path)));

    try {
      return parseSszDepositSnapshotTreeData(snapshotData);
    } catch (final SszDeserializeException e) {
      return parseJsonDepositSnapshotTreeData(snapshotData);
    }
  }

  private static DepositTreeSnapshot parseSszDepositSnapshotTreeData(final Bytes snapshotData) {
    return DepositTreeSnapshot.fromBytes(snapshotData);
  }

  private static DepositTreeSnapshot parseJsonDepositSnapshotTreeData(final Bytes snapshotData)
      throws JsonProcessingException {
    final String json = new String(snapshotData.toArray(), StandardCharsets.UTF_8);
    final JsonNode jsonNode = new ObjectMapper().readTree(json);
    return JsonUtil.parse(
        jsonNode.get("data").toString(), DepositTreeSnapshot.getJsonTypeDefinition());
  }

  public static class DepositSnapshotResource {
    private final String path;
    private final boolean required;

    public DepositSnapshotResource(final String path, final boolean required) {
      this.path = path;
      this.required = required;
    }

    public String getPath() {
      return path;
    }

    public boolean isRequired() {
      return required;
    }

    @Override
    public boolean equals(final Object o) {
      if (this == o) {
        return true;
      }
      if (o == null || getClass() != o.getClass()) {
        return false;
      }
      final DepositSnapshotResource that = (DepositSnapshotResource) o;
      return required == that.required && Objects.equals(path, that.path);
    }

    @Override
    public int hashCode() {
      return Objects.hash(path, required);
    }

    @Override
    public String toString() {
      return "DepositSnapshotResource{path='" + path + "', required=" + required + '}';
    }
  }

  public static class Builder {
    private final List<DepositSnapshotResource> depositSnapshotResources = new ArrayList<>();

    public Builder addRequiredResource(final String path) {
      return addResource(path, true);
    }

    public Builder addOptionalResource(final String path) {
      return addResource(path, false);
    }

    private Builder addResource(final String path, final boolean required) {
      if (StringUtils.isNotBlank(path)) {
        depositSnapshotResources.add(new DepositSnapshotResource(path, required));
      }
      return this;
    }

    public DepositSnapshotFileLoader build() {
      return new DepositSnapshotFileLoader(depositSnapshotResources);
    }
  }
}
